test('normalization refuses every malformed version and container combination', () => {
  const reasonOf = (document) => {
    try { normalizeRoster(document); return null } catch (err) { return err.reason }
  }
  // A v1 body merely RELABELLED version 2 is the document crew/roster.schema.json
  // refuses; boot performs no schema validation, so it must be refused here too.
  assert.equal(reasonOf({ ...roster, schema_version: 2 }), 'roster-version-mismatch')
  assert.equal(reasonOf({ ...rosterV2Doc, schema_version: 1 }), 'roster-version-mismatch')
  assert.equal(reasonOf({ ...roster, schema_version: 3 }), 'roster-version-unknown')
  const incomplete = structuredClone(rosterV2Doc)
  delete incomplete.assurances[ASSURANCE_NAMES.at(-1)]
  assert.equal(reasonOf(incomplete), 'roster-seating-incomplete')
  const strayKeyed = structuredClone(roster)
  strayKeyed.tiers.b353stray = strayKeyed.tiers[ROSTER_V1_ORDER[0]]
  assert.equal(reasonOf(strayKeyed), 'roster-seating-unknown')
  // A v1 container keyed by a CANONICAL preset is the same mismatch, seen from
  // the key side: v1 seats aliases, and only aliases.
  const canonicalInV1 = { ...roster, tiers: rosterV2Doc.assurances }
  assert.equal(reasonOf(canonicalInV1), 'roster-seating-unknown')
  assert.equal(reasonOf({ ...roster, assurances: rosterV2Doc.assurances }), 'roster-seating-both')
  assert.equal(reasonOf({ models: roster.models }), 'roster-seating-absent')
  assert.equal(reasonOf(null), 'roster-seating-absent')
})

